# Chronologically frozen conditional conversion-factor and direct-exposure models.
.cr_ead_regression<-function(d,y,w){total<-sum(w);weighted<-d*sqrt(w);s<-svd(weighted,nu=0,nv=0)$d;if(length(s)<ncol(d)||tail(s,1)<=s[1]*1e-10) .cr_error('RANK_DEFICIENT','Exposure regression requires full weighted design rank');coefficient<-as.vector(qr.solve(weighted,y*sqrt(w),tol=1e-10));residual<-y-as.vector(d%*%coefficient);bread<-tryCatch(solve(crossprod(d,d*w)),error=function(e).cr_error('NUMERICAL_FAILURE','Exposure information outside finite invertible range'));covariance<-bread%*%crossprod(d,d*(w*residual^2))%*%bread;variance<-sum(w*residual^2)/total;if(any(!is.finite(coefficient))||any(!is.finite(covariance))||!is.finite(variance)) .cr_error('NUMERICAL_FAILURE','Exposure regression outside finite range');list(coefficients=as.list(coefficient),covariance=.cr_lgd_matrix_rows(covariance),covariance_type='HC0_FREQUENCY_IID',residual_variance=variance,rank=ncol(d),frequency_total=total)}
fit_ead_model<-function(exposure_episodes,X_train,feature_order,target_mode,model_spec,target,training,model_id,model_version,currency,weights=NULL,minimum_undrawn=0,fit_intercept=TRUE,context=NULL){
 ctx<-.cr_lgd_currency(currency,context);des<-.cr_glm_design(X_train,feature_order,fit_intercept);x<-des$x;d<-des$d;rows<-.cr_data_rows(exposure_episodes,'exposure_episodes');.cr_data_unique(rows,'episode_id','exposure_episodes');if(length(rows)!=nrow(x)) .cr_error('INCOMPATIBLE_SHAPE','One exposure episode per design row required');if(!(target_mode%in%c('ccf','direct_ead'))) .cr_error('EAD_MODEL_SPEC','Declare ccf or direct_ead target mode')
 if(!.cr_object(target)||!identical(target$event,'ead')||!identical(target$probability_measure,'PHYSICAL')||!identical(target$conditioning,'given_default')||!identical(target$time_unit,'days')||!identical(target$currency,currency)) .cr_error('TARGET_MISMATCH','Exposure target requires PHYSICAL, given_default, integer-day horizon and currency');ctx<-.cr_lgd_target_context(target,ctx,model_version);if(!.cr_object(training)) .cr_error('INVALID_MODEL','Training metadata must be an object');horizon<-.cr_data_days(target$horizon,'target.horizon',1);cutoff<-.cr_data_date(training$known_at,'training.known_at');threshold<-.cr_lgd_scalar(minimum_undrawn,'minimum_undrawn',0);w<-if(is.null(weights))rep(1,nrow(x)) else .cr_numeric(weights,'weights',vector_only=TRUE)
 if(length(w)!=nrow(x)||any(w<0)||any(w!=floor(w))||!any(w>0)||!is.finite(sum(w))||sum(w)>2^53-1) .cr_error('INVALID_WEIGHTS','Positive total exact integer frequency weights required');targets<-numeric();valid<-integer();excluded<-list()
 for(i in seq_along(rows)){row<-rows[[i]];.cr_data_required(row,c('reference_date','reference_known_at','default_date','default_known_at','features_observed_at','features_known_at','reference_drawn','reference_limit','ead_at_default','currency'));ref<-.cr_data_date(row$reference_date,'reference_date');known<-.cr_data_date(row$reference_known_at,'reference_known_at');default<-.cr_data_date(row$default_date,'default_date');dk<-.cr_data_date(row$default_known_at,'default_known_at');fo<-.cr_data_date(row$features_observed_at,'features_observed_at');fk<-.cr_data_date(row$features_known_at,'features_known_at')
 if(row$currency!=currency||known>ref||ref>=default||default>dk||dk>cutoff||fo>ref||fk>ref||fk<fo||as.numeric(default-ref)!=horizon) .cr_error('EXPOSURE_DATE','Reference/feature dates must be frozen before default at the exact target lookback and known by training cutoff');drawn<-.cr_lgd_scalar(row$reference_drawn,'reference_drawn',0);limit<-.cr_lgd_scalar(row$reference_limit,'reference_limit',0);ead<-.cr_lgd_scalar(row$ead_at_default,'ead_at_default',0)
 if(target_mode=='ccf'){denominator<-.cr_loss_sum(c(limit,-drawn));if(denominator<=threshold){excluded[[length(excluded)+1L]]<-list(episode_id=row$episode_id,reason=if(denominator<=0)'NO_POSITIVE_UNDRAWN' else 'BELOW_MINIMUM_UNDRAWN');next};value<-.cr_loss_sum(c(ead,-drawn))/denominator;if(!is.finite(value)) .cr_error('NUMERICAL_FAILURE','Realized CCF outside finite range')}else value<-ead
 if(w[i]>0){valid<-c(valid,i);targets<-c(targets,value)}}
 if(!length(valid)) .cr_error('INSUFFICIENT_EXPOSURE_SUPPORT','No positive-weight eligible exposure rows remain');da<-d[valid,,drop=FALSE];xa<-x[valid,,drop=FALSE];ya<-targets;wa<-w[valid];params<-list(target_mode=target_mode,model_spec=model_spec,fit_intercept=fit_intercept,currency=currency,minimum_undrawn=threshold,feature_min=as.list(apply(xa,2,min)),feature_max=as.list(apply(xa,2,max)),weight_type='frequency')
 if(target_mode=='ccf'){
  if(!.cr_object(model_spec)||!identical(.cr_hash(model_spec),.cr_hash(list(mean_model='identity',covariance='HC0')))) .cr_error('EAD_MODEL_SPEC','CCF requires identity conditional mean and HC0 frequency covariance');params$regression<-.cr_ead_regression(da,ya,wa);params$distribution_identified<-FALSE
 }else{
  if(!.cr_object(model_spec)||!setequal(names(model_spec),c('positive_distribution','zero_model'))||!identical(model_spec$positive_distribution,'lognormal')||!(model_spec$zero_model%in%c('none','logit','all_zero'))) .cr_error('EAD_MODEL_SPEC','Direct EAD requires lognormal amount and zero_model none/logit/all_zero');positive<-ya>0;zero_model<-model_spec$zero_model;params$distribution_identified<-TRUE
  if(zero_model=='all_zero'){if(any(positive)) .cr_error('EAD_COMPONENT_SUPPORT','all_zero requires all active EAD targets equal zero');params<-c(params,list(positive_probability=0,positive_regression=NULL,positive_gate=NULL))}else{
   if(!any(positive)||(zero_model=='none'&&!all(positive))||(zero_model=='logit'&&all(positive))) .cr_error('EAD_COMPONENT_SUPPORT','Declared zero/positive stages must have the required positive-weight support');params$positive_feature_min<-as.list(apply(xa[positive,,drop=FALSE],2,min));params$positive_feature_max<-as.list(apply(xa[positive,,drop=FALSE],2,max));params$positive_regression<-.cr_ead_regression(da[positive,,drop=FALSE],log(ya[positive]),wa[positive]);if(params$positive_regression$residual_variance<=1e-24) .cr_error('NON_IDENTIFIABLE','Lognormal positive amount requires nonzero residual dispersion');params<-c(params,list(positive_probability=if(zero_model=='none')1 else NULL,positive_gate=NULL))
   if(zero_model=='logit'){gate_target<-target;gate_target$event<-'positive_ead_given_default';params$positive_gate<-fit_binary_glm(xa,as.numeric(positive),'logit',feature_order,fit_intercept,gate_target,training,paste0(model_id,':positive'),model_version,weights=wa)$model}
  }
 }
 diagnostics<-list(eligible_rows=length(valid),excluded_rows=excluded,frequency_total=sum(wa),weight_type='frequency',target_mode=target_mode,feature_cutoff='observed_and_known_at_or_before_reference',target_lookback_days=horizon)
 model<-.cr_model(list(schema_version='1.0',model_id=model_id,model_version=model_version,method_id='ead.fit_ead_model',feature_order=as.list(des$feature_order),parameters=params,preprocessing=list(transformation='identity'),target=target,training=training,diagnostics=diagnostics,provenance=list(data_origin=if(is.null(training$data_origin))'USER_SUPPLIED' else training$data_origin,parameter_origin='ESTIMATED'),input_fingerprint=.cr_hash(list(episodes=rows,X=.cr_lgd_matrix_rows(x),weights=as.list(w)))))
 .cr_fit_result(model,'ead.fit_ead_model',diagnostics=diagnostics,context=ctx)
}
predict_ead<-function(fitted_model_or_schedule,facility_covariates,feature_order,expected_target,reference_dates,default_dates,currency,reference_drawn=NULL,reference_limit=NULL,quantile_levels=NULL,context=NULL){
 ctx<-.cr_lgd_currency(currency,context);src<-if(inherits(fitted_model_or_schedule,'CalcResult')&&!inherits(fitted_model_or_schedule,'FitResult'))fitted_model_or_schedule$value else fitted_model_or_schedule
 if(.cr_object(src)&&!is.null(src$schedule_hash)){
  frozen<-src;digest<-frozen$schedule_hash;frozen$schedule_hash<-NULL;if(!identical(digest,.cr_hash(frozen))) .cr_error('INTEGRITY_ERROR','Exposure schedule content differs from its binding');if(!identical(src$currency,currency)||!is.null(facility_covariates)||length(feature_order)||!is.null(expected_target)||!is.null(reference_drawn)||!is.null(reference_limit)||!is.null(quantile_levels)) .cr_error('EXPOSURE_CONVENTION','Schedule prediction takes exact dates and currency, without regression inputs')
  dates<-.cr_ead_chars(default_dates);refs<-.cr_ead_chars(reference_dates);if(!is.character(dates)||!length(dates)||!identical(refs,rep(src$as_of,length(dates)))) .cr_error('EXPOSURE_DATE','Schedule reference dates must equal its frozen as_of');lookup<-setNames(lapply(src$schedule,`[[`,'conditional_ead'),vapply(src$schedule,`[[`,character(1),'period_end'));if(any(!(dates%in%names(lookup)))) .cr_error('EXPOSURE_DATE','Schedule default dates must match explicit period endpoints')
  return(.cr_result(list(conditional_ead=unname(lookup[dates]),default_dates=as.list(dates),reference_dates=as.list(refs),currency=currency,source='EXPOSURE_SCHEDULE',quantile_levels=NULL,quantiles=NULL),'ead.predict_ead',currency,ctx,diagnostics=list(schedule_hash=digest)))
 }
 model<-.cr_model(fitted_model_or_schedule);p<-model$parameters;ctx<-.cr_lgd_target_context(model$target,ctx,model$model_version)
 if(!identical(model$method_id,'ead.fit_ead_model')||!identical(as.list(feature_order),model$feature_order)||!identical(.cr_hash(expected_target),.cr_hash(model$target))||!identical(p$currency,currency)) .cr_error('TARGET_MISMATCH','Frozen EAD method, target, currency and feature order must match');des<-.cr_glm_design(facility_covariates,feature_order,p$fit_intercept);x<-des$x;d<-des$d;n<-nrow(x);refs<-.cr_ead_chars(reference_dates);dates<-.cr_ead_chars(default_dates)
 if(!is.character(refs)||!is.character(dates)||length(refs)!=n||length(dates)!=n) .cr_error('EXPOSURE_DATE','One reference/default date per prediction required')
 for(i in seq_len(n)){ref<-.cr_data_date(refs[i],'reference_date');if(ref<.cr_data_date(model$training$known_at,'training.known_at')||as.numeric(.cr_data_date(dates[i],'default_date')-ref)!=model$target$horizon) .cr_error('EXPOSURE_DATE','Prediction reference-to-default horizon must match training target')}
 levels<-if(is.null(quantile_levels))NULL else .cr_numeric(quantile_levels,'quantile_levels',vector_only=TRUE);if(!is.null(levels)&&(any(levels<=0|levels>=1)||any(diff(levels)<=0))) .cr_error('INVALID_QUANTILE','Strictly increasing interior probabilities required');lo<-.cr_lgd_parameter_vector(p$feature_min,'feature_min',allow_empty=TRUE);hi<-.cr_lgd_parameter_vector(p$feature_max,'feature_max',allow_empty=TRUE);if(length(lo)!=ncol(x)||length(hi)!=length(lo)) .cr_error('INVALID_MODEL','Frozen EAD support dimension mismatch')
 outside<-if(ncol(x))rowSums(sweep(x,2,lo,'<')|sweep(x,2,hi,'>'))>0 else rep(FALSE,n);diagnostics<-list(model_id=model$model_id,model_fingerprint=.cr_hash(model),outside_marginal_training_range=as.list(outside));value<-list(default_dates=as.list(dates),reference_dates=as.list(refs),currency=currency,source='FITTED_MODEL',quantile_levels=if(is.null(levels))NULL else as.list(levels),quantiles=NULL)
 if(p$target_mode=='ccf'){
  if(!is.null(levels)) .cr_error('DISTRIBUTION_NOT_IDENTIFIED','CCF conditional mean does not identify exposure quantiles');drawn<-.cr_numeric(reference_drawn,'reference_drawn',vector_only=TRUE);limit<-.cr_numeric(reference_limit,'reference_limit',vector_only=TRUE);if(length(drawn)!=n||length(limit)!=n||any(drawn<0)||any(limit<0)) .cr_error('EXPOSURE_INPUT','Aligned nonnegative reference drawn and limits required');denominator<-limit-drawn;if(any(denominator<=p$minimum_undrawn)) .cr_error('INSUFFICIENT_EXPOSURE_SUPPORT','Prediction undrawn must exceed the frozen CCF threshold');beta<-.cr_lgd_parameter_vector(p$regression$coefficients,'coefficients');if(length(beta)!=ncol(d)) .cr_error('INVALID_MODEL','CCF coefficient dimension mismatch');ccf<-as.vector(d%*%beta);ead<-vapply(seq_len(n),function(i).cr_loss_sum(c(drawn[i],.cr_loss_multiply(denominator[i],ccf[i]))),numeric(1));if(any(ead<0)) .cr_error('NEGATIVE_EAD_PREDICTION','Raw CCF conditional mean implies negative exposure; revise model/support rather than clipping');cov<-do.call(rbind,lapply(p$regression$covariance,function(r).cr_lgd_parameter_vector(r,'covariance row')));if(!identical(dim(cov),c(ncol(d),ncol(d)))) .cr_error('INVALID_MODEL','CCF covariance dimension mismatch');mv<-rowSums((d%*%cov)*d);if(any(mv<0)||any(!is.finite(mv))) .cr_error('NUMERICAL_FAILURE','CCF mean covariance outside nonnegative finite range');se<-sqrt(mv);ead_se<-.cr_loss_multiply(denominator,se);value<-c(value,list(conditional_ead=as.list(ead),conditional_ccf=as.list(ccf),conditional_ccf_mean_standard_error=as.list(se),conditional_ead_mean_standard_error=as.list(ead_se),distribution=NULL))
 }else if(p$target_mode=='direct_ead'){
  if(!is.null(reference_drawn)||!is.null(reference_limit)) .cr_error('EXPOSURE_CONVENTION','Direct EAD regression does not consume CCF reconstruction amounts')
  if(p$model_spec$zero_model=='all_zero'){positive<-rep(0,n);mu<-rep(0,n);variance<-0;ead<-rep(0,n);quantiles<-if(is.null(levels))NULL else matrix(0,n,length(levels))}else{
   pl<-.cr_lgd_parameter_vector(p$positive_feature_min,'positive_feature_min',allow_empty=TRUE);ph<-.cr_lgd_parameter_vector(p$positive_feature_max,'positive_feature_max',allow_empty=TRUE);if(length(pl)!=length(lo)||length(ph)!=length(lo)) .cr_error('INVALID_MODEL','Positive-stage support dimension mismatch');if(ncol(x))diagnostics$outside_marginal_training_range<-as.list(unlist(diagnostics$outside_marginal_training_range)|(rowSums(sweep(x,2,pl,'<')|sweep(x,2,ph,'>'))>0));regression<-p$positive_regression;beta<-.cr_lgd_parameter_vector(regression$coefficients,'coefficients');variance<-.cr_lgd_scalar(regression$residual_variance,'residual_variance',0);if(length(beta)!=ncol(d)) .cr_error('INVALID_MODEL','Positive amount coefficient dimension mismatch');mu<-as.vector(d%*%beta);positive<-if(is.null(p$positive_gate))rep(1,n) else as.numeric(unlist(predict_pd(p$positive_gate,x,feature_order,p$positive_gate$target)$value));ead<-positive*exp(mu+variance/2);quantiles<-NULL
   if(!is.null(levels)){quantiles<-matrix(0,n,length(levels));for(i in seq_len(n))for(j in seq_along(levels)){u<-levels[j];if(u>1-positive[i])quantiles[i,j]<-exp(mu[i]-sqrt(variance)*qnorm((1-u)/positive[i]))}}
  }
  if(any(!is.finite(ead))||(!is.null(quantiles)&&any(!is.finite(quantiles)))) .cr_error('NUMERICAL_FAILURE','Direct EAD mean or quantiles outside finite range');value$quantiles<-if(is.null(quantiles))NULL else .cr_lgd_matrix_rows(quantiles);if(is.null(quantiles))value['quantiles']<-list(NULL);value<-c(value,list(conditional_ead=as.list(ead),positive_probability=as.list(positive),distribution='ZERO_HURDLE_LOGNORMAL'))
 }else .cr_error('INVALID_MODEL','Unknown EAD target mode')
 .cr_result(value,'ead.predict_ead',currency,ctx,diagnostics=diagnostics,provenance=model$provenance,limitations='Conditional on the frozen default horizon. CCF means are unbounded working regressions, not loss distributions; negative implied exposure is rejected. Lognormal amount quantiles require the fitted distributional assumption and independent training observations.')
}
